INSERT INTO feature VALUES('induction-recursion','universes','Inductive-recursive definitions','tarski-universes','implemented','notable',NULL,'A mutual block whose data''s constructor types mention the functions defined with it, a universe indexed by a level among them; Dybjer and Setzer''s codes and the arguments each asks for check as data; a datatype that holds the `irSignature` role is the canonical signature type of `ι`, `σ` and `δ`, one that holds `irPair` the canonical dependent pair, and the holders of `irArgs` and `irDecode` answer the canonical `E` and `F` at each code; the checker refuses another holder as `BuiltinMark.NotCanonical`, and the kernel, which reads each holder''s role off the artifact, refuses it too.','core-term core-checker kernel-term kernel-core surface-lowering','corpus/model/universe/inductive-recursive.gandr corpus/pathological/universe/inductive-recursive.gandr corpus/model/universe/ir-codes.gandr corpus/pathological/universe/ir-codes.gandr corpus/model/universe/fresh-lists.gandr corpus/model/universe/pair-and-path-codes.gandr corpus/pathological/universe/pair-and-path-codes.gandr','corpus/model/universe/inductive-recursive.gandr','');
